#!/usr/bin/env bash
# Usage: check-one.sh <PR> <ref>   (run after merge-one.sh, in ${WT:-/home/user/wt})
# Regenerates generated files the PR's code may change, then typegen, tsc and the
# tests of the touched files. Writes logs to the scratchpad.
set -u
S=/tmp/claude-0/-home-user-marktmorgen/840044e9-b6db-557f-ad53-ac5781de3272/scratchpad
n=$1; ref=$2
cd ${WT:-/home/user/wt} || exit 9
changed=$(git diff --name-only origin/main...HEAD; git diff --name-only origin/main HEAD)
changed=$(echo "$changed" | sort -u)
# Regenerate only when the PR's own code feeds the generator; keep the result for review.
if echo "$changed" | grep -qE '^app/.*page\.tsx$|^lib/accessibility|^docs/accessibility-inventory'; then node scripts/accessibility-route-inventory.mjs --write > $S/gen-$n.log 2>&1; fi
if echo "$changed" | grep -qE '^lib/|^tests/(plan-cost|pricing|store-data|margin)'; then
  node scripts/pricing-optimization.mjs >> $S/gen-$n.log 2>&1
  node scripts/pricing-usage-proposal.mjs >> $S/gen-$n.log 2>&1
  node scripts/margin-alignment.mjs >> $S/gen-$n.log 2>&1
fi
# The statement's digest reads the regenerated records: recompute it after them (redigest.sh), never before.
if git status --porcelain | grep -q 'docs/accessibility-inventory.json'; then $S/redigest.sh > /dev/null; git reset -q -- lib/accessibility-statement.ts; fi
regen=$(git status --porcelain | awk '{print $2}')
npx next typegen > $S/tg-$n.log 2>&1 || { echo "TYPEGEN FAIL $n"; exit 4; }
NODE_OPTIONS=--max-old-space-size=6144 npx tsc --noEmit -p . > $S/tsc-$n.log 2>&1; tscrc=$?
errs=$(grep -c "error TS" $S/tsc-$n.log); [ $tscrc != 0 ] && [ "$errs" = 0 ] && errs=CRASH
# Tests: test files the PR changes, plus tests that import a changed lib/app/component module.
tests=$(echo "$changed" | grep -E '^tests/[^/]+\.test\.ts$' | sed 's#^tests/##')
for f in $(echo "$changed" | grep -E '^(lib|components|app)/.*\.tsx?$' | grep -v '\.test\.'); do
  m=${f%.*}; m=${m%/route}; m=${m%/page}
  tests="$tests $(grep -lF -e "@/${m}\"" -e "@/${f%.*}\"" tests/*.test.ts 2>/dev/null | head -12 | sed 's#^tests/##')"
done
tests=$(echo $tests | tr ' ' '\n' | grep . | sort -u | head -40)
for h in $(echo "$changed" | grep -E '^tests/[^/]+\.(ts|mjs)$' | grep -v '\.test\.ts$'); do b=$(basename ${h%.*}); [ -f tests/$b.test.ts ] && tests="$tests $b.test.ts"; tests="$tests $(grep -lE "from \"\./$b(\.ts)?\"" tests/*.test.ts 2>/dev/null | head -8 | sed 's#^tests/##')"; done
for g in $regen; do case "$g" in lib/accessibility-statement.ts) tests="$tests accessibility-statement.test.ts";; docs/accessibility-inventory.json) tests="$tests accessibility-route-inventory.test.ts";; docs/pricing-*|docs/margin-alignment*) tests="$tests pricing-optimization.test.ts pricing-usage-proposal.test.ts margin-alignment.test.ts";; esac; done
tests="$tests reservation-check.test.ts"
tests=$(echo $tests | tr ' ' '\n' | grep . | sort -u)
node $S/run-some.mjs ${WT:-/home/user/wt} $tests > $S/test-$n.log 2>&1; trc=$?
node scripts/reservation-check.mjs "$ref" origin/main > $S/resv-$n.log 2>&1; rrc=$?
echo "CHECK $n tsc_errors=$errs tests_rc=$trc $(tail -1 $S/test-$n.log) resv_rc=$rrc regen=[$regen]"
if [ "$errs" = 0 ] && [ $trc = 0 ] && [ $rrc = 0 ]; then
  if [ -n "$regen" ]; then
    git add -A -- $regen
    { head -3 $S/msg-$n.txt; echo "Generated files regenerated by their scripts on the merged tree and checked by their tests: $(echo $regen | tr '\n' ' ')"; tail -n +4 $S/msg-$n.txt; } > $S/msg2-$n.txt
    if git rev-parse -q --verify HEAD^2 >/dev/null; then git commit -q --amend -F $S/msg2-$n.txt
    else { echo "chore: regenerate generated files after the merge of main"; echo; echo "Regenerated by their scripts on the merged tree and checked by their tests: $(echo $regen | tr '\n' ' ')"; cat $S/trailer.txt; } > $S/msg3-$n.txt; git commit -q -F $S/msg3-$n.txt; fi
  fi
  git update-ref refs/heads/prep/$n HEAD; echo "PREP $n $(git rev-parse --short=10 HEAD)"
else echo "NOT READY $n"; fi
